content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-border: #bfdbfe;
  --success-color: #10b981;
  --success-light: #ecfdf5;
  --success-border: #a7f3d0;
  --bg-gradient-start: #f8fafc;
  --bg-gradient-end: #e2e8f0;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-container {
  max-width: 920px;
  margin: 0 auto;
  padding: 24px 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダー */
.header {
  text-align: center;
  padding: 12px 0 8px;
}

.title {
  font-size: 1.75rem;
  font-weight: 800;
  color: #1e293b;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* メインレイアウト */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* 変換入力カード */
.converter-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.input-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.number-input {
  width: 100%;
  padding: 12px 16px;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast);
}

.number-input:focus {
  background-color: #ffffff;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.number-input::placeholder {
  color: var(--text-light);
  font-weight: 400;
}

.select-wrapper {
  position: relative;
  display: flex;
  gap: 10px;
  align-items: center;
}

.unit-select {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition-fast), background-color var(--transition-fast);
  appearance: auto;
}

.unit-select:focus {
  background-color: #ffffff;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.reset-btn {
  padding: 12px 20px;
  font-size: 0.9rem;
  font-weight: 600;
  color: #475569;
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
  touch-action: manipulation;
}

.reset-btn:hover {
  background-color: #e2e8f0;
  color: var(--text-main);
}

.reset-btn:active {
  transform: translateY(1px);
}

/* プリセットセクション */
.presets-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  border-top: 1px dashed var(--border-color);
  padding-top: 16px;
}

.presets-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.preset-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.preset-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #334155;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: 9999px;
  cursor: pointer;
  transition: all var(--transition-fast);
  touch-action: manipulation;
}

.preset-chip:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
  transform: translateY(-1px);
}

.preset-chip:active {
  transform: translateY(0);
}

.preset-note {
  font-size: 0.75rem;
  color: var(--text-muted);
  opacity: 0.85;
}

/* 結果グリッドセクション */
.results-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.results-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 4px;
}

.results-count {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.result-card {
  background: var(--card-bg);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.result-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
}

.result-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.result-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: #1e293b;
}

.result-symbol {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: #f1f5f9;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}

.result-value-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.result-value {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--primary-color);
  word-break: break-all;
  line-height: 1.2;
}

.copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #475569;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
  touch-action: manipulation;
}

.copy-btn:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
}

.copy-btn-success {
  background-color: var(--success-light) !important;
  border-color: var(--success-border) !important;
  color: var(--success-color) !important;
}

.result-formula {
  font-size: 0.75rem;
  color: var(--text-light);
  line-height: 1.3;
}

/* 早見表セクション */
.formula-section {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.formula-table {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.formula-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  background-color: #f8fafc;
  font-size: 0.85rem;
}

.formula-row:nth-child(even) {
  background-color: #ffffff;
  border: 1px solid #f1f5f9;
}

.formula-unit {
  font-weight: 600;
  color: #334155;
}

.formula-rate {
  font-family: monospace, monospace;
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* フッター */
.footer {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-muted);
  padding-top: 8px;
}

/* モバイル対応レスポンシブ */
@media (max-width: 600px) {
  .app-container {
    padding: 16px 12px 32px;
    gap: 18px;
  }

  .title {
    font-size: 1.4rem;
  }

  .converter-card {
    padding: 18px 14px;
    gap: 16px;
  }

  .select-wrapper {
    flex-direction: column;
    align-items: stretch;
  }

  .reset-btn {
    width: 100%;
    padding: 10px;
    text-align: center;
  }

  .results-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .result-value {
    font-size: 1.2rem;
  }

  .formula-section {
    padding: 16px;
  }

  .formula-row {
    font-size: 0.8rem;
    padding: 6px 8px;
  }
}

