/**
 * 数値を人間が見やすい形式にフォーマットする関数
 */
export function formatNumber(num: number): string {
  if (isNaN(num)) return '0';
  if (num === 0) return '0';

  const absNum = Math.abs(num);

  // 極端に小さい値または極端に大きい値の場合は指数表記
  if ((absNum < 0.000001 && absNum > 0) || absNum >= 1e12) {
    return num.toExponential(4);
  }

  // 浮動小数点誤差を抑えるため有効数字最大8桁で丸め
  const precision = absNum < 1 ? 6 : absNum < 100 ? 5 : 4;
  const rounded = parseFloat(num.toPrecision(precision));

  // 整数部分と小数部分を分離して3桁区切りを適用
  const parts = rounded.toString().split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');

  return parts.join('.');
}

/**
 * 指定した単位からすべての単位へ長さを一括換算する関数
 */
export function convertLength(value: number, fromUnit: UnitKey): ConversionResult[] {
  const safeValue = isNaN(value) ? 0 : value;
  const sourceDefinition = UNITS[fromUnit];

  // 入力値を一度メートルに変換
  const valueInMeters = safeValue * sourceDefinition.toMeters;

  // 定義されている全単位の配列を作成して換算
  const unitKeys: UnitKey[] = ['mm', 'cm', 'm', 'km', 'inch', 'ft'];

  return unitKeys.map((key) => {
    const targetDefinition = UNITS[key];
    const convertedRawValue = valueInMeters / targetDefinition.toMeters;

    return {
      key,
      name: targetDefinition.name,
      symbol: targetDefinition.symbol,
      value: convertedRawValue,
      formattedValue: formatNumber(convertedRawValue),
    };
  });
}

