import { useState, useCallback } from 'react';
import { UnitKey, ConversionResult } from '../types';
import { UNITS } from '../utils/converter';

interface UnitGridProps {
  results?: ConversionResult[];
  currentUnit: UnitKey;
  onSelectAsSource?: (unit: UnitKey) => void;
}

const UnitGrid = ({
  results = [],
  currentUnit,
  onSelectAsSource,
}: UnitGridProps) => {
  const [copiedKey, setCopiedKey] = useState<UnitKey | null>(null);

  const handleCopy = useCallback((key: UnitKey, formattedValue: string) => {
    // 3桁カンマを除去した純粋な数値も扱いやすいようにカンマ除去
    const rawNumberStr = formattedValue.replace(/,/g, '');
    navigator.clipboard.writeText(rawNumberStr).then(() => {
      setCopiedKey(key);
      setTimeout(() => {
        setCopiedKey((prev) => (prev === key ? null : prev));
      }, 1500);
    }).catch(() => {
      // クリップボードAPIが失敗した場合のフォールバック
      setCopiedKey(key);
      setTimeout(() => {
        setCopiedKey((prev) => (prev === key ? null : prev));
      }, 1500);
    });
  }, []);

  return (
    <div className="results-section">
      <div className="results-header">
        <span className="results-count">換算結果（全{results.length}単位）</span>
      </div>
      <div className="results-grid">
        {results.map((result) => {
          const isCopied = copiedKey === result.key;
          const isCurrent = result.key === currentUnit;
          const unitDef = UNITS[result.key];

          return (
            <div key={result.key} className="result-card">
              <div className="result-header">
                <span className="result-name">{result.name}</span>
                <span className="result-symbol">{result.symbol}</span>
              </div>
              <div className="result-value-row">
                <span className="result-value">{result.formattedValue}</span>
                <button
                  type="button"
                  className={isCopied ? "copy-btn copy-btn-success" : "copy-btn"}
                  onClick={() => handleCopy(result.key, result.formattedValue)}
                  title="数値をクリップボードにコピー"
                >
                  {isCopied ? 'コピー完了' : 'コピー'}
                </button>
              </div>
              <div className="result-formula">
                {unitDef ? unitDef.description : ''}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default UnitGrid;

import { useState, useMemo, ChangeEvent } from 'react';
import { UnitKey } from './types';
import { UNITS, PRESETS, convertLength } from './utils/converter';
import QuickPresets from './components/QuickPresets';
import UnitGrid from './components/UnitGrid';

const unitOptions: UnitKey[] = ['mm', 'cm', 'm', 'km', 'inch', 'ft'];

const App = () => {
  const [inputValue, setInputValue] = useState<string>('1');
  const [selectedUnit, setSelectedUnit] = useState<UnitKey>('m');

  const parsedValue = useMemo(() => {
    const num = parseFloat(inputValue);
    return isNaN(num) ? 0 : num;
  }, [inputValue]);

  const conversionResults = useMemo(() => {
    return convertLength(parsedValue, selectedUnit);
  }, [parsedValue, selectedUnit]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // 数値および小数点のみ入力許可（空文字も許可）
    if (val === '' || /^-?\d*\.?\d*$/.test(val)) {
      setInputValue(val);
    }
  };

  const handleUnitChange = (e: ChangeEvent<HTMLSelectElement>) => {
    setSelectedUnit(e.target.value as UnitKey);
  };

  const handleReset = () => {
    setInputValue('1');
    setSelectedUnit('m');
  };

  const handleSelectPreset = (presetValue: number, presetUnit: UnitKey) => {
    setInputValue(presetValue.toString());
    setSelectedUnit(presetUnit);
  };

  const handleSelectAsSource = (unit: UnitKey) => {
    setSelectedUnit(unit);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">長さ単位一括換算ツール</h1>
        <p className="subtitle">
          mm・cm・m・km・インチ・フィートをリアルタイムに相互変換します
        </p>
      </header>

      <main className="main-layout">
        <section className="converter-card">
          <div className="input-section">
            <div className="input-group">
              <label htmlFor="length-input" className="label">
                <span>変換したい長さの数値を入力</span>
              </label>
              <input
                id="length-input"
                type="text"
                inputMode="decimal"
                className="number-input"
                value={inputValue}
                onChange={handleInputChange}
                placeholder="数値を入力 (例: 100)"
              />
            </div>

            <div className="input-group">
              <label htmlFor="unit-select" className="label">
                <span>入力元の単位</span>
              </label>
              <div className="select-wrapper">
                <select
                  id="unit-select"
                  className="unit-select"
                  value={selectedUnit}
                  onChange={handleUnitChange}
                >
                  {unitOptions.map((key) => {
                    const def = UNITS[key];
                    return (
                      <option key={key} value={key}>
                        {def.name} ({def.symbol})
                      </option>
                    );
                  })}
                </select>
                <button
                  type="button"
                  className="reset-btn"
                  onClick={handleReset}
                >
                  リセット
                </button>
              </div>
            </div>
          </div>

          <QuickPresets
            presets={PRESETS}
            onSelectPreset={handleSelectPreset}
          />
        </section>

        <UnitGrid
          results={conversionResults}
          currentUnit={selectedUnit}
          onSelectAsSource={handleSelectAsSource}
        />

        <section className="formula-section">
          <div className="presets-title">単位の基準値・換算比率早見表</div>
          <div className="formula-table">
            {unitOptions.map((key) => {
              const def = UNITS[key];
              return (
                <div key={key} className="formula-row">
                  <span className="formula-unit">
                    1 {def.symbol} ({def.name})
                  </span>
                  <span className="formula-rate">
                    = {def.toMeters} m ({def.description})
                  </span>
                </div>
              );
            })}
          </div>
        </section>
      </main>

      <footer className="footer">
        © 長さ単位一括換算ツール - mm・cm・m・km・インチ・フィート相互変換
      </footer>
    </div>
  );
};

export default App;
